// HMAC-SHA256: header x-mf-signature = 'sha256=' + hex(HMAC(secret, rawBody))
// Secret comes from n8n env var N8N_WEBHOOK_SECRET (injected at container boot).
const crypto = require('crypto');

const secret = process.env.N8N_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('N8N_WEBHOOK_SECRET env var not set on n8n container');
}

const rawBody = $input.first().binary?.data
  ? Buffer.from($input.first().binary.data, 'base64').toString()
  : JSON.stringify($input.first().json);

const incomingSig = $input.first().headers?.['x-mf-signature'] ?? '';
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(rawBody).digest('hex');

if (!crypto.timingSafeEqual(Buffer.from(incomingSig), Buffer.from(expected))) {
  throw new Error('HMAC signature mismatch — request rejected');
}

return $input.all();

// Required fields: org_id, content_item_id, platforms[], post{text}, profileKey
// Optional: post.title, post.hashtags[], media[]{url, kind}

const body = $input.first().json;

const required = ['org_id', 'content_item_id', 'platforms', 'post', 'profileKey'];
const missing = required.filter(k => body[k] === undefined || body[k] === null || body[k] === '');
if (missing.length) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}
if (!Array.isArray(body.platforms) || body.platforms.length === 0) {
  throw new Error('platforms must be a non-empty array');
}
if (typeof body.post?.text !== 'string' || !body.post.text.trim()) {
  throw new Error('post.text must be a non-empty string');
}

// Platform name mapping: our internal name -> Ayrshare accepted names
const PLATFORM_MAP = {
  x: 'twitter',
  instagram: 'instagram',
  facebook: 'facebook',
  linkedin: 'linkedin',
  youtube: 'youtube',
  tiktok: 'tiktok',
};

const mappedPlatforms = body.platforms.map(p => {
  const mapped = PLATFORM_MAP[p];
  if (!mapped) throw new Error(`Unknown platform: ${p}`);
  return mapped;
});

// Instagram requires at least one media item; YouTube requires a video.
const hasInstagram = body.platforms.includes('instagram');
const hasYoutube = body.platforms.includes('youtube');
const media = Array.isArray(body.media) ? body.media : [];

if (hasInstagram && media.length === 0) {
  throw new Error('Instagram requires at least one media item in body.media');
}
if (hasYoutube) {
  const hasVideo = media.some(m => m.kind === 'video');
  if (!hasVideo) throw new Error('YouTube requires a video item in body.media');
}

// Build Ayrshare-compatible post body
const ayrsharePost = {
  post: body.post.text,
  platforms: mappedPlatforms,
  ...(body.post.hashtags?.length ? { hashtags: body.post.hashtags } : {}),
  ...(body.post.title ? { title: body.post.title } : {}),
  ...(media.length > 0 ? { mediaUrls: media.map(m => m.url) } : {}),
};

return [{
  json: {
    _meta: {
      org_id: body.org_id,
      content_item_id: body.content_item_id,
      originalPlatforms: body.platforms,
    },
    profileKey: body.profileKey,
    ayrsharePost,
  }
}];

const meta = $('Validate & Normalise Payload').first().json._meta;
const ayrRes = $input.first().json;
const statusCode = $input.first().json?.statusCode ?? 200;

// Ayrshare success: { status:'success', postIds:[{platform, id, postUrl}] }
// Ayrshare error:  { status:'error', errors:[{action, log, platform}] }

let results = [];

const PLATFORM_REVERSE_MAP = {
  twitter: 'x',
  instagram: 'instagram',
  facebook: 'facebook',
  linkedin: 'linkedin',
  youtube: 'youtube',
  tiktok: 'tiktok',
};

if (ayrRes.status === 'success' && Array.isArray(ayrRes.postIds)) {
  results = ayrRes.postIds.map(entry => ({
    platform: PLATFORM_REVERSE_MAP[entry.platform] ?? entry.platform,
    externalPostId: entry.id ?? null,
    postUrl: entry.postUrl ?? null,
    status: 'published',
    error: null,
  }));
} else {
  // Error or partial failure — map errors array or synthesise from top-level error
  const errors = Array.isArray(ayrRes.errors) ? ayrRes.errors : [];
  results = meta.originalPlatforms.map(p => {
    const platformErr = errors.find(e => (PLATFORM_REVERSE_MAP[e.platform] ?? e.platform) === p);
    return {
      platform: p,
      externalPostId: null,
      postUrl: null,
      status: 'failed',
      error: platformErr?.log ?? ayrRes.message ?? `HTTP ${statusCode}`,
    };
  });
}

return [{ json: { results, _meta: meta } }];

// Build a normalised failure response so the worker always gets a consistent shape.
const err = $input.first().json?.error ?? $input.first().json?.message ?? 'Unknown error in wf-publish';
const body = $('Webhook — POST wf-publish').first()?.json ?? {};

return [{
  json: {
    results: (body.platforms ?? ['unknown']).map(p => ({
      platform: p,
      externalPostId: null,
      postUrl: null,
      status: 'failed',
      error: String(err),
    })),
    _error: String(err),
  }
}];
